<?php
$absoluteImage = static function (?string $path): string {
    $url = upload_url($path);
    return preg_match('#^https?://#i', $url) ? $url : rtrim((string) config('app.url'), '/') . '/' . ltrim($url, '/');
};
$paymentLabel = $order['payment_method'] === 'online_card' ? 'Plată online prin Stripe' : $order['payment_method_label'];
?>
